from datetime import datetime
from django.db import migrations, models
from django.utils import timezone


# 追加した列は0で埋まるため、登録済みの月次統計(Stats)に1度でも模倣されたことのある作者数を計算して入れる（#1163）
# subekashi/lib/stats_service.pyのcompute_imitated_author_count・apply_songrange_filterと
# statsコマンドの月の境界の決め方のコピー。lib側を後から変えても、このマイグレーションの挙動が変わらないよう、importせずにコピーしている
def fill_total_imitated_authors(apps, schema_editor):
    Author = apps.get_model('subekashi', 'Author')
    Song = apps.get_model('subekashi', 'Song')
    Stats = apps.get_model('subekashi', 'Stats')
    for stats in Stats.objects.all():
        if stats.month == 12:
            next_year, next_month = stats.year + 1, 1
        else:
            next_year, next_month = stats.year, stats.month + 1
        # 履歴モデルのマネージャーは削除した曲(is_removed=True)を除外しないため、明示的に除外する
        songs = Song.objects.filter(is_removed=False, upload_time__lt=timezone.make_aware(datetime(next_year, next_month, 1)))
        if stats.songrange == 'subeana':
            songs = songs.filter(is_subeana=True)
        elif stats.songrange == 'xx':
            songs = songs.filter(is_subeana=False)
        imitated_songs = songs.filter(imitateds__is_removed=False)
        stats.total_imitated_authors = Author.objects.filter(songs__in=imitated_songs).distinct().count()
        stats.save(update_fields=['total_imitated_authors'])


